package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"mime"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

var files = map[string][]byte{}

func main() {
	port := os.Getenv("PORT")
	if port == "" { port = "3000" }

	http.HandleFunc("/upload/", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.Method != "PUT" { http.NotFound(w, r); return }
		name := strings.TrimPrefix(r.URL.Path, "/upload/")
		data, _ := io.ReadAll(r.Body)
		files[name] = data
		json.NewEncoder(w).Encode(map[string]interface{}{"name": name, "size": len(data)})
	})

	http.HandleFunc("/stream/", func(w http.ResponseWriter, r *http.Request) {
		name := strings.TrimPrefix(r.URL.Path, "/stream/")
		data, ok := files[name]
		if !ok { w.WriteHeader(404); return }
		ext := filepath.Ext(name)
		mimeType := mime.TypeByExtension(ext)
		if mimeType == "" { mimeType = "application/octet-stream" }
		w.Header().Set("Content-Type", mimeType)
		w.Header().Set("Content-Length", fmt.Sprintf("%d", len(data)))
		io.Copy(w, bytes.NewReader(data))
	})

	http.ListenAndServe(":"+port, nil)
}

