package main

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"strconv"
	"strings"
)

var files = map[string][]byte{}

func main() {
	port := os.Getenv("PORT")
	if port == "" { port = "3000" }

	http.HandleFunc("/upload/", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.Method != "PUT" { http.NotFound(w, r); return }
		name := strings.TrimPrefix(r.URL.Path, "/upload/")
		data, _ := io.ReadAll(r.Body)
		files[name] = data
		json.NewEncoder(w).Encode(map[string]string{"name": name})
	})

	http.HandleFunc("/stream/", func(w http.ResponseWriter, r *http.Request) {
		name := strings.TrimPrefix(r.URL.Path, "/stream/")
		data, ok := files[name]
		if !ok { w.WriteHeader(404); return }
		rangeHeader := r.Header.Get("Range")
		if rangeHeader != "" {
			parts := strings.Split(strings.Replace(rangeHeader, "bytes=", "", 1), "-")
			start, _ := strconv.Atoi(parts[0])
			end := len(data) - 1
			if len(parts) > 1 && parts[1] != "" {
				end, _ = strconv.Atoi(parts[1])
			}
			if start >= len(data) { w.WriteHeader(416); return }
			chunk := data[start:end+1]
			w.Header().Set("Content-Range", fmt.Sprintf("bytes %d-%d/%d", start, end, len(data)))
			w.Header().Set("Content-Length", fmt.Sprintf("%d", len(chunk)))
			w.WriteHeader(206)
			w.Write(chunk)
			return
		}
		w.Write(data)
	})

	http.ListenAndServe(":"+port, nil)
}

