const express = require('express');
const { Readable } = require('stream');
const app = express();
const port = process.env.PORT || 3000;
app.get('/stream/large', (req, res) => {
  const size = 100 * 1024 * 1024;
  let sent = 0;
  res.set('Content-Type', 'application/octet-stream');
  res.set('Content-Length', size);
  function writeChunk() {
    while (sent < size) {
      const chunkSize = Math.min(64 * 1024, size - sent);
      const chunk = Buffer.alloc(chunkSize, 'A');
      sent += chunkSize;
      if (!res.write(chunk)) { res.once('drain', writeChunk); return; }
    }
    res.end();
  }
  writeChunk();
});
app.listen(port);

