package main

import (
	"fmt"
	"net/http"
	"os"
)

func main() {
	port := os.Getenv("PORT")
	if port == "" { port = "3000" }

	http.HandleFunc("/stream/large", func(w http.ResponseWriter, r *http.Request) {
		size := 100 * 1024 * 1024
		w.Header().Set("Content-Type", "application/octet-stream")
		w.Header().Set("Content-Length", fmt.Sprintf("%d", size))
		chunk := make([]byte, 64*1024)
		for i := range chunk { chunk[i] = 'C' }
		sent := 0
		for sent < size {
			toWrite := len(chunk)
			if sent+toWrite > size { toWrite = size - sent }
			n, _ := w.Write(chunk[:toWrite])
			sent += n
		}
	})

	http.ListenAndServe(":"+port, nil)
}
